import { Component, createMemo, createSignal, For, JSX, onCleanup, onMount } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface TextureAtlas {
	/** Path/url to texture atlas */
	src: string;
	/** Width (pixels) of each sprite within the sheet */
	spriteWidth: number;
	/** Height (pixels) of each sprite within the sheet */
	spriteHeight: number;
	/** Length (pixels) of atlas. Assumes atlas is a square */
	size: number;
	/** Number of frames inside the atlas. If undefined, will assume that the entire atlas is filled */
	nFrames?: number;
}

export interface FlipbookProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/** An array of texture atlases used as the source of the animation frames */
	atlas: TextureAtlas[];
	/** The frames per second of the animation */
	fps: number;
}

const FlipbookComponent: Component<FlipbookProps> = (props: FlipbookProps) => {
	let elapsed = 0;
	let lastFrameTime = 0;
	let frameHandler: number | undefined;

	const atlases = createMemo(() =>
		props.atlas.map((atlas) => {
			const [isActive, setIsActive] = createSignal(false);
			const [xPos, setXPos] = createSignal(0);
			const [yPos, setYPos] = createSignal(0);

			const rows = atlas.size / atlas.spriteHeight;
			const cols = atlas.size / atlas.spriteWidth;
			const frames = atlas.nFrames ?? rows * cols;
			const duration = (frames / props.fps) * 1000;
			const src = atlas.src;

			return { isActive, setIsActive, xPos, setXPos, yPos, setYPos, rows, cols, frames, duration, src };
		}),
	);

	const totalFrames = createMemo(() => atlases().reduce((sum, a) => sum + a.frames, 0));
	const totalDuration = createMemo(() => atlases().reduce((sum, a) => sum + a.duration, 0));

	function showFrame(totalFrame: number) {
		let offset = 0;
		for (const atlas of atlases()) {
			const atlasFrame = totalFrame - offset;
			if (atlasFrame >= 0 && atlasFrame < atlas.frames) {
				const row = Math.floor(atlasFrame / atlas.cols);
				const col = Math.floor(atlasFrame % atlas.cols);
				atlas.setXPos(100 * (col / (atlas.cols - 1)));
				atlas.setYPos(100 * (row / (atlas.rows - 1)));
				atlas.setIsActive(true);
			} else {
				atlas.setIsActive(false);
			}

			offset += atlas.frames;
		}
	}

	function updateFrame(timestamp: DOMHighResTimeStamp) {
		if (lastFrameTime != 0) {
			elapsed += timestamp - lastFrameTime;
			elapsed %= totalDuration();
		}

		lastFrameTime = timestamp;
		showFrame(Math.floor((totalFrames() * elapsed) / totalDuration()));
		frameHandler = requestAnimationFrame(updateFrame);
	}

	onMount(() => {
		lastFrameTime = 0;
		frameHandler = requestAnimationFrame(updateFrame);
	});

	onCleanup(() => {
		if (frameHandler) {
			cancelAnimationFrame(frameHandler);
			frameHandler = undefined;
		}
	});

	return (
		<div>
			<For each={atlases()}>
				{(atlas) => (
					<div
						{...props}
						classList={{ hidden: !atlas.isActive() }}
						style={{
							background: `url("${atlas.src}")`,
							"background-size": `${atlas.cols * 100}% ${atlas.rows * 100}%`,
							"background-position-x": `${atlas.xPos()}%`,
							"background-position-y": `${atlas.yPos()}%`,
						}}
					/>
				)}
			</For>
		</div>
	);
};

export type FlipbookComponents = Component<FlipbookProps> & {
	/**
	 * A Turning Hourglass Flipbook
	 * Default implementation: {@link HourglassComponent} Based on: {@link Flipbook}
	 */
	Hourglass: Component<JSX.HTMLAttributes<HTMLDivElement>>;
};

/**
 * A Flipbook component
 * Used to show a sprite animation sourced from one or more texture atlases
 * Default implementation: {@link FlipbookComponent}
 * @param {FlipbookProps} props See {@link FlipbookProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {TextureAtlas[]} props.atlas An array of texture atlases used as the source of the animation frames
 * @param {boolean} props.fps The frames per second of the animation
 *
 * Predefined animations are included as properties:
 * {@link Flipbook.Hourglass}
 */
export const Flipbook = ComponentRegistry.register(
	"Flipbook",
	FlipbookComponent,
) as Component<FlipbookProps> as FlipbookComponents;

const HourglassComponent: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<Flipbook
			{...props}
			fps={30}
			atlas={[
				{ src: "blp:hourglasses01", spriteHeight: 128, spriteWidth: 128, size: 512 },
				{ src: "blp:hourglasses02", spriteHeight: 128, spriteWidth: 128, size: 512 },
				{ src: "blp:hourglasses03", spriteHeight: 128, spriteWidth: 128, size: 1024, nFrames: 13 },
			]}
		/>
	);
};

Flipbook.Hourglass = ComponentRegistry.register({
	name: "Flipbook.Hourglass",
	createInstance: HourglassComponent,
	images: ["blp:hourglasses01", "blp:hourglasses02", "blp:hourglasses03"],
});
